-- counters, as PunBB itself would have maintained them
UPDATE topics t SET num_replies = (SELECT COUNT(*) - 1 FROM posts p WHERE p.topic_id = t.id), last_post_id = (SELECT MAX(id) FROM posts p WHERE p.topic_id = t.id);
UPDATE topics t JOIN posts p ON p.id = t.last_post_id SET t.last_post = p.posted, t.last_poster = p.poster;
UPDATE forums f SET num_topics = (SELECT COUNT(*) FROM topics t WHERE t.forum_id = f.id), num_posts = (SELECT COUNT(*) FROM posts p JOIN topics t ON t.id = p.topic_id WHERE t.forum_id = f.id), last_post_id = (SELECT MAX(p.id) FROM posts p JOIN topics t ON t.id = p.topic_id WHERE t.forum_id = f.id);
UPDATE forums f JOIN posts p ON p.id = f.last_post_id SET f.last_post = p.posted, f.last_poster = p.poster;
UPDATE users u SET num_posts = (SELECT COUNT(*) FROM posts p WHERE p.poster_id = u.id), last_post = (SELECT MAX(posted) FROM posts p WHERE p.poster_id = u.id) WHERE u.id > 1;
