INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (1, 'mkay', 2, '81.152.40.17', '1. Search before you post. Most questions have been asked already.
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (2, 's_h', 5, '70.49.122.31', 'Building an old release of a tool from source and gcc 4.0 stops with:
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (3, 'retupmoc', 4, '67.171.92.4', 'Cast-as-lvalue was a GNU extension and it was removed in 4.0. Write it as p = (char *)p + len; or build that one package with gcc-3.4.', UNIX_TIMESTAMP('2005-12-02 21:34:50'), 2);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (4, 's_h', 5, '70.49.122.31', 'That did it, thanks. Two more of those further down, same fix.', UNIX_TIMESTAMP('2005-12-02 22:02:16'), 2);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (5, 'dref', 6, '24.86.170.9', 'Rails hit 1.0 this week. I''ve been doing PHP at work for three years and every screencast makes me want to try it. Anyone here built something real with it, or is it all blog-in-15-minutes videos?', UNIX_TIMESTAMP('2005-12-15 03:20:48'), 3);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (6, 'pkg', 10, '70.112.8.203', 'Built an internal ticket tracker on 0.13 over the summer. Very productive for CRUD stuff; deployment is the painful part. FastCGI under Apache fell over a few times a week until we moved it to lighttpd.', UNIX_TIMESTAMP('2005-12-15 15:02:11'), 3);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (7, 'lpr', 12, '203.206.14.92', 'Learning Ruby is the bigger investment than learning Rails. Do a few weeks of plain Ruby first or the magic won''t make sense.', UNIX_TIMESTAMP('2005-12-16 09:45:37'), 3);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (8, 'dref', 6, '24.86.170.9', 'Spent most of December checking stock at three different shops and finally got one the day after Christmas. Project Gotham 3 looks unreal on a decent TV.', UNIX_TIMESTAMP('2005-12-27 08:00:13'), 4);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (9, 'pkg', 10, '70.112.8.203', 'Still waiting on a preorder from November. At this point I''ll just buy a Revolution.', UNIX_TIMESTAMP('2005-12-27 15:30:44'), 4);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (10, 'ahz', 11, '83.27.150.66', 'Can''t justify the price yet. Still working through Half-Life 2 on the PC.', UNIX_TIMESTAMP('2005-12-28 10:00:39'), 4);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (11, 'mkay', 2, '81.152.40.17', 'Almost two years of this board now. Happy 2006 everyone, thanks for keeping it civil, and thanks to horic for doing most of the actual moderating.', UNIX_TIMESTAMP('2006-01-01 00:20:04'), 5);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (12, 'lpr', 12, '203.206.14.92', 'Happy new year. You lot are ten hours late.', UNIX_TIMESTAMP('2006-01-01 00:45:31'), 5);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (13, 'horic', 3, '195.113.26.80', 'Happy new year. Mostly I just move threads out of the wrong forum.', UNIX_TIMESTAMP('2006-01-01 11:30:15'), 5);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (14, 'tnorr', 7, '130.238.7.55', 'Gott nytt ar.', UNIX_TIMESTAMP('2006-01-01 13:02:50'), 5);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (15, 'tnorr', 7, '130.238.7.55', 'The ones worth mentioning: The Practice of Programming (reread), Hackers & Painters, and Snow Crash for the first time, somehow.', UNIX_TIMESTAMP('2006-01-02 18:00:25'), 6);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (16, 'horic', 3, '195.113.26.80', 'Code Complete, 2nd edition. Long, but it earns it.', UNIX_TIMESTAMP('2006-01-02 19:15:03'), 6);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (17, 'retupmoc', 4, '67.171.92.4', 'Practical Common Lisp. Didn''t change my day job, did change how I write elisp.', UNIX_TIMESTAMP('2006-01-03 01:00:52'), 6);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (18, 'segv', 9, '212.183.40.6', '2.6.15 is up on kernel.org. Long shortlog as usual. Anyone tried it yet? Mostly I want to know if the in-tree ipw2200 is finally usable.', UNIX_TIMESTAMP('2006-01-03 08:20:51'), 7);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (19, 'kbuild', 8, '84.56.211.140', 'Running it since this afternoon on the desktop, no problems so far. The nvidia 1.0-8178 module needs rebuilding after you boot it, obviously.', UNIX_TIMESTAMP('2006-01-03 19:45:30'), 7);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (20, 'tnorr', 7, '130.238.7.55', 'ipw2200 works for me on 2.6.15 with the 2.4 firmware. WPA through wpa_supplicant, no complaints.', UNIX_TIMESTAMP('2006-01-04 07:30:18'), 7);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (21, 'horic', 3, '195.113.26.80', 'Waiting for the first .1 like always.', UNIX_TIMESTAMP('2006-01-04 10:10:02'), 7);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (22, 'segv', 9, '212.183.40.6', 'Linux Device Drivers, 3rd edition. Free online, so no excuse.', UNIX_TIMESTAMP('2006-01-04 12:20:18'), 6);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (23, 'tnorr', 7, '130.238.7.55', 'Four developers, one CVS repository from 2001, about 9000 commits. Has anyone run cvs2svn on something that size? Mostly worried about branches and binary files that were never marked -kb.', UNIX_TIMESTAMP('2006-01-05 13:12:40'), 8);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (24, 'pkg', 10, '70.112.8.203', 'Did it last summer with a repo about twice that. cvs2svn took a couple of hours and got everything except two branches that had been created in odd ways. Fix -kb on your binaries before converting, not after.', UNIX_TIMESTAMP('2006-01-05 14:30:22'), 8);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (25, 'mkay', 2, '81.152.40.17', 'What people like after switching: renames are real and commits are atomic. What they hate: tags are just copies and nothing stops you committing to one.', UNIX_TIMESTAMP('2006-01-05 18:55:09'), 8);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (26, 'retupmoc', 4, '67.171.92.4', 'Post your setup. Mine: Athlon XP 2500+, 1 GB, two 19" CRTs that weigh more than the desk, and a Model M from 1989.', UNIX_TIMESTAMP('2006-01-06 20:00:38'), 9);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (27, 'kbuild', 8, '84.56.211.140', 'Athlon 64 3200+, 1 GB, 6600GT, one 19" LCD. Gave up on CRTs when I moved flat.', UNIX_TIMESTAMP('2006-01-06 21:10:09'), 9);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (28, 's_h', 5, '70.49.122.31', 'Hand-me-down Dell, Duron 1.2 and 256 MB, see the XFCE thread. 15" monitor. Saving for something better.', UNIX_TIMESTAMP('2006-01-07 10:30:46'), 9);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (29, 'kbuild', 8, '84.56.211.140', 'Our host is moving us from 4.4 to 5.1 next month. Mostly small custom sites, plus one board running this same software. What breaks?', UNIX_TIMESTAMP('2006-01-07 11:00:14'), 10);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (30, 'mkay', 2, '81.152.40.17', 'Old OO code is the big one: objects are passed by handle now, so anything that relied on copies behaves differently. This board runs fine on 5.x.', UNIX_TIMESTAMP('2006-01-07 12:30:51'), 10);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (31, 'retupmoc', 4, '67.171.92.4', 'Also code that passes non-arrays to the array functions. 5 is stricter about that and the warnings will fill your logs.', UNIX_TIMESTAMP('2006-01-07 14:10:26'), 10);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (32, 'lpr', 12, '203.206.14.92', '12" PowerBook G4, plus an old P2 under the desk running Debian as a server. The Mac is for work, the server is for fun.', UNIX_TIMESTAMP('2006-01-07 14:45:21'), 9);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (33, 'ahz', 11, '83.27.150.66', 'Since going to 1.5 Firefox sits at 180 MB after a day with ten tabs. Is this the famous leak or am I doing something wrong?', UNIX_TIMESTAMP('2006-01-08 15:00:22'), 11);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (34, 'segv', 9, '212.183.40.6', 'Part of it is the new back/forward cache, it keeps rendered pages in memory. Set browser.sessionhistory.max_total_viewers to 0 in about:config and see if it improves.', UNIX_TIMESTAMP('2006-01-08 15:40:59'), 11);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (35, 'segv', 9, '212.183.40.6', 'Fine here too. Only thing that broke was an out-of-tree lirc module, which is apparently tradition.', UNIX_TIMESTAMP('2006-01-08 20:55:47'), 7);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (36, 'ahz', 11, '83.27.150.66', 'Down to about 110 MB with that. Adblock was holding onto something too, disabled it for now.', UNIX_TIMESTAMP('2006-01-08 21:20:13'), 11);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (37, 'dref', 6, '24.86.170.9', 'Extensions are usually the problem. Try a clean profile before blaming the browser.', UNIX_TIMESTAMP('2006-01-09 02:10:48'), 11);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (38, 'tnorr', 7, '130.238.7.55', 'Converted over the weekend, took 50 minutes. Two people already asked why svn log is so slow over http, so I''m setting up svnserve for them.', UNIX_TIMESTAMP('2006-01-09 09:20:33'), 8);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (39, 'pkg', 10, '70.112.8.203', 'Dual Opteron box that work was throwing out. Loud. Wife hates it.', UNIX_TIMESTAMP('2006-01-09 12:00:57'), 9);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (40, 'retupmoc', 4, '67.171.92.4', 'New guy at work asked which one to learn and two of us nearly came to blows. So: which do you use, and why. Bonus points for reasons other than "it''s what I learned first".', UNIX_TIMESTAMP('2006-01-10 22:15:30'), 12);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (41, 'lpr', 12, '203.206.14.92', 'vim. vi is on every box I ssh into, including the Solaris ones, and vim is close enough that my fingers don''t care.', UNIX_TIMESTAMP('2006-01-10 22:31:12'), 12);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (42, 'retupmoc', 4, '67.171.92.4', 'emacs, because M-x compile and jumping straight to errors, gdb inside the editor, and dired. Also twelve years of .emacs that I''m not throwing away.', UNIX_TIMESTAMP('2006-01-10 22:47:55'), 12);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (43, 'kbuild', 8, '84.56.211.140', '[quote=retupmoc]gdb inside the editor[/quote]
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (44, 'pkg', 10, '70.112.8.203', 'nano. Fight me.', UNIX_TIMESTAMP('2006-01-11 09:40:02'), 12);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (45, 'tnorr', 7, '130.238.7.55', 'Learn enough vi to fix a config file on a broken system, then use whatever you like. That''s the only advice that matters.', UNIX_TIMESTAMP('2006-01-11 12:22:47'), 12);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (46, 'pkg', 10, '70.112.8.203', 'Upgraded to 2.6.15 and the vendor driver for a USB DVB stick won''t build any more:
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (47, 'horic', 3, '195.113.26.80', 'class_simple went away in 2.6.13. Either port it to class_create/class_device_create or check whether the stick is supported in-tree by now; a lot of DVB-USB devices are.', UNIX_TIMESTAMP('2006-01-11 19:10:58'), 13);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (48, 'pkg', 10, '70.112.8.203', 'It''s in-tree as dvb-usb-dtt200u. Removed the vendor junk, modprobe, works. Feel slightly stupid.', UNIX_TIMESTAMP('2006-01-12 09:55:03'), 13);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (49, 's_h', 5, '70.49.122.31', 'GNOME on the old Duron is crawling. Thinking about XFCE 4.2. Anyone use it full time? What do you miss?', UNIX_TIMESTAMP('2006-01-12 16:10:03'), 14);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (50, 'dref', 6, '24.86.170.9', 'Have done since spring. Thunar isn''t in 4.2 so the file manager is xffm, which is ugly but works. Nothing else I miss.', UNIX_TIMESTAMP('2006-01-12 16:55:42'), 14);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (51, 'lpr', 12, '203.206.14.92', 'auth.log on my home server is full of ssh brute force attempts from all over the place. Password auth is already off. Is fail2ban worth it at that point or is it just log noise?', UNIX_TIMESTAMP('2006-01-12 22:30:40'), 15);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (52, 'tnorr', 7, '130.238.7.55', 'If password auth is off they aren''t getting in. I moved sshd to a high port mostly so the logs are readable again.', UNIX_TIMESTAMP('2006-01-12 23:05:16'), 15);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (53, 'lpr', 12, '203.206.14.92', 'Xubuntu is apparently going to be an official flavour for Dapper. Until then just apt-get install xfce4 on top of Breezy.', UNIX_TIMESTAMP('2006-01-13 08:30:19'), 14);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (54, 'ahz', 11, '83.27.150.66', 'Reviving a P2-350 with 128 MB for my sister. GNOME and KDE are out. What would you put on it?', UNIX_TIMESTAMP('2006-01-13 12:00:27'), 16);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (55, 'horic', 3, '195.113.26.80', 'fluxbox. Right-click menu, tabs, done. Uses maybe 5 MB.', UNIX_TIMESTAMP('2006-01-13 12:40:09'), 16);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (56, 'retupmoc', 4, '67.171.92.4', 'IceWM if she''s coming from Windows. Taskbar and a start button, nobody has to learn anything.', UNIX_TIMESTAMP('2006-01-13 13:15:44'), 16);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (57, 'kbuild', 8, '84.56.211.140', 'Rebuilding a few things with GCC 4.0.2 on an Athlon 64. Is there any point in -O3 for general stuff, or is -O2 -march=athlon64 -pipe where everyone ends up? The Gentoo forums are full of people swearing by flags they never measured.', UNIX_TIMESTAMP('2006-01-13 19:30:44'), 17);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (58, 'horic', 3, '195.113.26.80', '-O3 mostly adds more aggressive inlining and -funswitch-loops, so binaries get bigger, and on a lot of code they get slower because of cache pressure. Use -O2 unless you have a benchmark that says otherwise.', UNIX_TIMESTAMP('2006-01-13 20:05:10'), 17);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (59, 'mkay', 2, '81.152.40.17', 'Run it anyway, it costs nothing. And put AllowUsers in sshd_config so only your account can log in at all.', UNIX_TIMESTAMP('2006-01-13 20:11:34'), 15);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (60, 'segv', 9, '212.183.40.6', 'And -ffast-math is not a free speedup, whatever people say. It drops IEEE semantics and I''ve watched it break a physics sim in very creative ways.', UNIX_TIMESTAMP('2006-01-13 20:41:29'), 17);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (61, 's_h', 5, '70.49.122.31', 'Installed it last night. Login to usable desktop went from about 40 seconds to 12. Staying.', UNIX_TIMESTAMP('2006-01-13 22:40:55'), 14);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (62, 'kbuild', 8, '84.56.211.140', 'Quick test with lame, same WAV, best of five runs:
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (63, 'horic', 3, '195.113.26.80', 'Matches what most people find. The one place I''ve seen -O3 matter is tight numeric loops, and there you should be profiling anyway.', UNIX_TIMESTAMP('2006-01-14 15:47:21'), 17);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (64, 'horic', 3, '195.113.26.80', 'Been running Breezy on the laptop for about two months now. apt-get is apt-get, nothing new there, but the installer is a lot less painful than Debian''s if you don''t want to think about partitioning for twenty minutes. Suspend to RAM even works on the ThinkPad, which sarge never managed.
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (65, 'retupmoc', 4, '67.171.92.4', '[quote=horic]Still not sure I''d put it on a server over sarge though.[/quote]
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (66, 'dref', 6, '24.86.170.9', 'Turn off the compositor in xfwm4 if you switched it on for the shadows. Looks nice, eats a Duron alive.', UNIX_TIMESTAMP('2006-01-14 19:02:37'), 14);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (67, 'tnorr', 7, '130.238.7.55', 'Ubuntu only promises 18 months of security updates for 5.10. Sarge gets them until a year after etch is out, and etch isn''t even frozen yet. For servers that settles it for me.', UNIX_TIMESTAMP('2006-01-14 19:20:07'), 18);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (68, 's_h', 5, '70.49.122.31', 'I went from XP straight to Ubuntu last month and skipped Debian entirely out of impatience. So far the only thing that''s given me trouble is a winmodem, which is apparently on nobody''s priority list.', UNIX_TIMESTAMP('2006-01-14 20:15:40'), 18);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (69, 'segv', 9, '212.183.40.6', 'Seconding IceWM for a non-technical user. And give her Opera or Firefox 1.0.7 on that box, 1.5 will be painful in 128 MB.', UNIX_TIMESTAMP('2006-01-14 21:30:12'), 16);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (70, 'retupmoc', 4, '67.171.92.4', '[quote=tnorr]Learn enough vi to fix a config file on a broken system[/quote]
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (71, 'dref', 6, '24.86.170.9', 'Winmodems are a lost cause, get a cheap PCI hardware modem off eBay if you still need dialup for anything. Sounds like you got off easy compared to my Breezy install, which didn''t see the second monitor until I edited xorg.conf by hand:
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (72, 'segv', 9, '212.183.40.6', 'Dapper is supposed to be the long-term support release, 3 years on the desktop and 5 on servers. If that actually happens it changes the argument a bit. Due in April, so probably June.', UNIX_TIMESTAMP('2006-01-15 07:58:03'), 18);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (73, 'mkay', 2, '81.152.40.17', 'For what it''s worth I keep Debian stable on anything that needs to stay up and Ubuntu on anything I''m actively poking at. Not a very exciting answer but it''s held up for a year now.', UNIX_TIMESTAMP('2006-01-15 08:52:45'), 18);
INSERT INTO posts (id, poster, poster_id, poster_ip, message, posted, topic_id) VALUES (74, 'horic', 3, '195.113.26.80', 'Fair enough. Laptop stays on Breezy, the file server stays on sarge, and I''ll look again when Dapper is out.', UNIX_TIMESTAMP('2006-01-15 09:41:18'), 18);
INSERT INTO online (user_id, ident, logged, idle) VALUES (3, 'horic', UNIX_TIMESTAMP('2006-01-15 10:13:20'), 0), (9, 'segv', UNIX_TIMESTAMP('2006-01-15 10:14:05'), 0), (1, '66.249.65.12', UNIX_TIMESTAMP('2006-01-15 10:13:40'), 0), (1, '82.41.190.7', UNIX_TIMESTAMP('2006-01-15 10:14:30'), 0);
